contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries to call sendTo from this contract (which is not the original deployer/owner of c)
    // We take a receiver and amount; we send some Ether along to c first so there is balance to transfer.
    function run(address payable receiver, uint amount) public payable {
        require(address(this).balance >= msg.value);
        // Fund C so that sendTo could succeed if caller were owner
        // Transfer msg.value into c
        (bool ok,) = address(c).call{value: msg.value}("");
        // read balance before attempting send
        uint before = address(c).balance;

        bool reverted;
        // Attempt to call sendTo from this contract (this is not the constructor deployer => not owner)
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = address(c).balance;

        // General rule: since this contract is not the owner, sendTo must revert and c's balance must be unchanged
        assert(reverted && after == before);
    }

    receive() external payable {}
}

