        require(address(this).balance >= amount);
        // Fund C so it has at least `amount`
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);

        // Ensure the invoker of c.sendTo is the owner: the checker deploys C with owner = msg.sender at C's construction.
        // Our InvMutTest was the deployer of C, so calling via this contract should be from owner.
        uint beforeC = address(c).balance;
        uint beforeReceiver = receiver.balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterReceiver = receiver.balance;

        // General rule: if call did not revert, C's balance decreased by exactly amount and receiver's balance increased by at least amount
