contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // run attempts to call sendTo with arbitrary receiver and amount. The test contract is NOT the owner
    // because C was deployed freshly by the checker and its owner is the deployer (not this test).
    // We check whether the call reverts and that if it reverts then c's balance is unchanged, and
    // if it does not revert then c's balance decreased by exactly amount and the receiver's balance increased.
    // Because the test cannot observe arbitrary receiver balances, we only observe address(c).balance
    // and whether the call reverted. We require address(this).balance >= amount only to be able to send value when needed.

    function run(address payable receiver, uint256 amount) public payable {
        require(address(this).balance >= amount);

        uint256 before = address(c).balance;

        bool reverted;
        try c.sendTo{value: amount}(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule:
        // If the call reverted, contract balance must be unchanged. If it did not revert, balance must have decreased by amount.
        // This captures that sendTo either fails without moving Ether, or succeeds and transfers exactly amount out of C.
        assert(reverted ? after == before : before >= amount && after + amount == before);
    }

    receive() external payable {}
}

