contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = msg.sender; // deployer of test; note: C was already deployed fresh by the harness
    }

    // We take an address caller and an amount to attempt a transfer from c to receiver.
    // The test contract will call c.sendTo as itself (msg.sender == address(this) for c),
    // so to exercise owner vs non-owner behavior we rely on whether the freshly deployed C
    // set its owner to address(this) or to some other address. The harness deploys C fresh
    // with msg.sender = the harness, not this test, so in general address(this) is not owner.
    function run(address payable receiver, uint256 amount) public payable {
        require(receiver != address(0));
        // Ensure this contract has enough balance to forward if needed (not required by C but safe).
        // We will observe c's balance before and after the call and whether it reverted.
        uint256 beforeBalance = address(c).balance;
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;

        // General rule: If the call reverted then c's balance is unchanged; if it did not revert then
        // the call must have been made by the owner and c's balance decreased by at most the amount
        // (cannot underflow in assertion because we compare via >=). Also, if it succeeded then
        // afterBalance == beforeBalance - amount (or >= beforeBalance - amount if transfer failed silently),
        // but transfer uses transfer which will revert on failure, so equality should hold when succeeded.
        assert(
            // either reverted and balance unchanged
            (reverted && afterBalance == beforeBalance)
            ||
            // or not reverted and balance decreased exactly by amount
            (!reverted && beforeBalance >= amount && afterBalance == beforeBalance - amount)
        );
    }

    receive() external payable {}
}

