    // Require bounds so subtraction/comparisons in the assert are safe and meaningful.
    function run(address payable receiver, uint256 amount) public payable {
        require(receiver != address(0));
        // ensure the amount is not absurdly larger than c's balance to avoid pointless reverts
        uint256 beforeC = address(c).balance;
        uint256 beforeReceiver = receiver.balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterReceiver = receiver.balance;

        // If the call succeeded then C's balance decreased by exactly amount and receiver's increased by exactly amount.
        assert(reverted || (beforeC >= amount && afterC == beforeC - amount && afterReceiver == beforeReceiver + amount));
