contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // caller is this contract (which deployed C in harness), but we model calls from arbitrary addresses
    // by attempting a call via the test contract and observing whether it reverts. To check non-owner behavior
    // we require that the caller address used is different from the owner: here represented by an address param `caller`.
    // We cannot change msg.sender of calls to c, so instead we assert that if the caller param is not equal to the recorded
    // owner getter then a direct call from this contract must revert. This makes sense because the test contract is the owner
    // (deployer of C) in the harness; to assert non-owner behavior we require a receiver different from owner and use a proxy
    // by checking that when `caller` != owner, then the call from this contract (non-matching) must revert. To meet the
    // formal requirements we structure the test to assert: if caller != owner then calling sendTo from this contract reverts.

    // Note: we cannot actually change msg.sender when calling c, so we treat `caller` as an abstract address and compare
    // it to the public owner via c.owner(). The invariant we assert is: for any address `caller` different from c.owner(),
    // an attempt by this contract (which is NOT equal to `caller`) to call sendTo should revert. This is a conservative
    // property that will hold if only the owner can call sendTo successfully.

    function run(address payable receiver, uint256 amount, address caller) public payable {
        require(receiver != address(0));
        // read observable owner via auto-generated getter; note: C.owner is not public in original, so this will fail if no getter.
        // To follow constraints, only call public/externals. If owner has no getter, then we can't reference it; however in P owner is private,
        // so we must instead observe behavior: since this test contract deployed C, it is the owner. So we set a precondition that
        // `caller` is not equal to address(this) to represent non-owner, and then assert that calling sendTo from this contract (which is owner)
        // may or may not revert; but we need a general rule about non-owners must revert. Given constraints, we assert: if caller != address(this)
        // then a direct call from this contract when caller is different should not be allowed to succeed as if from `caller` — therefore it must revert.

        require(caller != address(this));

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the abstract caller differs from this contract (i.e., is a non-owner), then the attempted sendTo call must have reverted.
        // This captures that non-owners cannot successfully trigger sendTo.
        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking caller and amount parameters
    function run(address payable receiver, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // record contract C balance before the call
        uint256 beforeBal = address(c).balance;

        // Attempt the call and capture whether it reverted
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = address(c).balance;

        // General rule: if the call reverted then C's balance must be unchanged;
        // otherwise the caller must have been the owner (the contract that deployed C — msg.sender at deployment)
        // We cannot directly read owner (it's private), but we know deployment made owner = deployer.
        // Since the checker deploys a fresh C and passes this InvMutTest as msg.sender for interactions,
        // a successful call implies this contract was owner. We express this by: if not reverted then C's balance decreased by at most amount (i.e., amount was transferred out),
        // and if reverted then balance unchanged.
        // Formally: reverted => afterBal == beforeBal; !reverted => afterBal <= beforeBal && beforeBal - afterBal <= amount
        assert( (reverted && afterBal == beforeBal) || (
                !reverted && afterBal <= beforeBal && (beforeBal - afterBal) <= amount
            ) );
    }

    receive() external payable {}
}

